    decisions = []

    def reject(stage, reason, **fields):
        decisions.append({'stage': stage, 'eligible': False, 'reason': reason, **fields})

    for pid, product_rows in sorted(by_product.items()):
        title = product_rows[0]['title'].strip()
        reason = None
